{
  "name": "DIDV-850 POSTMAN {{run_id}} EXTENDED",
  "steps": [
    {
      "id": "ADVERSE_MEDIA"
    },
    {
      "id": "CUSTOM_PROMPT",
      "config": {
        "prompts": [
          {
            "text": "Capture a verification image"
          }
        ]
      }
    },
    {
      "id": "CONSENT",
      "config": {
        "consent_text": "I agree to this verification test.",
        "require_signature": false
      }
    },
    {
      "id": "BANK_STATEMENT_UPLOAD"
    },
    {
      "id": "AI_BANK_STATEMENT_ANALYSIS"
    },
    {
      "id": "DOCUMENT_UPLOAD",
      "config": {
        "documents": [
          {
            "id": "supporting_document",
            "description": "Supporting document"
          }
        ]
      }
    },
    {
      "id": "WHITE_LABEL"
    },
    {
      "id": "PHONE_TRUST_CHECK"
    },
    {
      "id": "CARRIER_AGE_GATE"
    },
    {
      "id": "PHONE_OWNERSHIP_MATCH"
    }
  ]
}

{
  "name": "DIDV-850 POSTMAN {{run_id}} PHONE",
  "steps": [
    {
      "id": "PHONE_VERIFICATION",
      "config": {
        "verification_prompt": "My voice confirms my identity"
      }
    }
  ]
}

{
  "name": "DIDV-850 POSTMAN {{run_id}} RUNNER",
  "steps": [
    {
      "id": "FACE_LIVENESS_CONSENT_SETTINGS",
      "config": {
        "face_liveness": false
      }
    },
    {
      "id": "CONSENT",
      "config": {
        "consent_text": "I agree to this automated dev verification.",
        "require_signature": false
      }
    },
    {
      "id": "WHITE_LABEL"
    }
  ]
}
